tool.implementation:
"""compact tool — manually trigger context compaction."""


async def execute(_engine=None, _plugin_provider=None, **kwargs) -> dict:
    """Manually invoke compaction via the compaction plugin."""
    if _plugin_provider is None:
        return {"ok": False, "error": "Plugin provider not available"}

    # Find the compaction plugin
    for plugin in _plugin_provider.list_plugins():
        if plugin.name == "compaction":
            from arf.core.plugin_context import PluginContext
            ctx = PluginContext(
                session_id=kwargs.get("session_id", "default"),
                interaction_round=0,
            )
            result = await plugin.compact_now(ctx, trigger="manual")
            return result

    return {"ok": False, "error": "Compaction plugin not found"}

"""create_directory tool — recursive directory creation."""

import os


async def execute(path: str, **kwargs) -> dict:
    existed = os.path.isdir(path)
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as e:
        return {"ok": False, "error": str(e)}

    return {"ok": True, "path": path, "created": not existed}

"""delete_file tool — delete files and directories."""

import os
import shutil


async def execute(path: str, recursive: bool = False, **kwargs) -> dict:
    if not os.path.exists(path):
        return {"ok": False, "error": f"Path does not exist: {path}"}

    try:
        if os.path.isfile(path) or os.path.islink(path):
            os.unlink(path)
        elif os.path.isdir(path):
            if recursive:
                shutil.rmtree(path)
            else:
                os.rmdir(path)  # fails if not empty
    except OSError as e:
        return {"ok": False, "error": str(e)}

    return {"ok": True, "path": path, "recursive": recursive}

"""directory_tree tool — recursive JSON tree of directory contents."""

import fnmatch
import os


def _build_tree(current_path: str, root_path: str, exclude_patterns: list[str]) -> list[dict]:
    entries = []
    try:
        with os.scandir(current_path) as it:
            for entry in it:
                relpath = os.path.relpath(os.path.join(current_path, entry.name), root_path)

                if _should_exclude(relpath, entry.is_dir(), exclude_patterns):
                    continue

                node: dict = {
                    "name": entry.name,
                    "type": "directory" if entry.is_dir() else "file",
                }

                if entry.is_dir():
                    node["children"] = _build_tree(
                        os.path.join(current_path, entry.name), root_path, exclude_patterns
                    )

                entries.append(node)
    except PermissionError:
        pass

    entries.sort(key=lambda x: (x["type"] != "directory", x["name"]))
    return entries


def _should_exclude(relpath: str, is_dir: bool, patterns: list[str]) -> bool:
    for pat in patterns:
        if fnmatch.fnmatch(relpath, pat):
            return True
        if fnmatch.fnmatch(relpath, f"**/{pat}"):
            return True
        if is_dir and fnmatch.fnmatch(relpath, f"**/{pat}/**"):
            return True
    return False


DEFAULT_EXCLUDES = [".git", ".venv", "venv", "__pycache__", "*.pyc", "node_modules"]


async def execute(path: str, excludePatterns: list[str] | None = None, **kwargs) -> dict:
    if not os.path.isdir(path):
        return {"ok": False, "error": f"Not a directory: {path}"}

    exclude = list(DEFAULT_EXCLUDES) + (excludePatterns or [])
    tree = _build_tree(path, path, exclude)

    return {"ok": True, "tree": tree}

"""edit_file tool — pattern-based file editing with unified diff output."""

import difflib
import os
import tempfile


def _normalize_line_endings(text: str) -> str:
    """Replace Windows CRLF with Unix LF."""
    return text.replace("\r\n", "\n")


def _create_unified_diff(original: str, modified: str, filepath: str) -> str:
    """Generate unified diff between original and modified content."""
    diff_lines = list(
        difflib.unified_diff(
            original.splitlines(keepends=True),
            modified.splitlines(keepends=True),
            fromfile=filepath,
            tofile=filepath,
        )
    )
    return "".join(diff_lines)


def _wrap_in_fence(diff_text: str) -> str:
    """Wrap diff text in a variable-sized backtick fence.

    Chooses a fence size at least 3 that does not conflict with
    any run of consecutive backticks inside the diff content.
    """
    max_run = 0
    current_run = 0
    for ch in diff_text:
        if ch == "`":
            current_run += 1
            max_run = max(max_run, current_run)
        else:
            current_run = 0

    fence_size = max(max_run + 1, 3)
    fence = "`" * fence_size
    return f"{fence}\n{diff_text}\n{fence}"


def _try_whitespace_flexible_match(
    content: str, old_text: str, new_text: str
) -> str | None:
    """Try to match *old_text* via line-level whitespace-flexible comparison.

    Each line is compared by ``.strip()``.  When all lines match, the
    indentation of the first matched line is carried over to the replacement.

    Returns the updated content on success, or ``None`` when no match is found.
    """
    old_lines = old_text.split("\n")
    content_lines = content.split("\n")
    new_text_lines = new_text.split("\n")

    # Determine the indentation of the first replacement line so we can
    # compute per-line relative indent adjustments.
    if new_text_lines:
        new_first_line = new_text_lines[0]
        new_first_indent_len = len(new_first_line) - len(new_first_line.lstrip())
    else:
        new_first_indent_len = 0

    for i in range(len(content_lines) - len(old_lines) + 1):
        # Check whether all lines match (whitespace-insensitive)
        match = True
        for j in range(len(old_lines)):
            if old_lines[j].strip() != content_lines[i + j].strip():
                match = False
                break

        if not match:
            continue

        # Capture original indentation of the first matched line
        first_content_line = content_lines[i]
        base_indent = first_content_line[
            : len(first_content_line) - len(first_content_line.lstrip())
        ]

        # Build replacement lines with preserved indentation
        replacement: list[str] = []
        for nl in new_text_lines:
            stripped = nl.lstrip()
            current_indent_len = len(nl) - len(stripped)
            relative_indent = " " * max(0, current_indent_len - new_first_indent_len)
            replacement.append(base_indent + relative_indent + stripped)

        content_lines[i : i + len(old_lines)] = replacement
        return "\n".join(content_lines)

    return None


async def execute(
    path: str, edits: list[dict], dryRun: bool = False,
    encoding: str = "utf-8", **kwargs
) -> dict:
    """Apply one or more text edits to a file and return a unified diff.

    Parameters
    ----------
    path :
        File to edit.
    edits :
        Sequence of ``{"oldText": …, "newText": …}`` edit operations.
    dryRun :
        When ``True`` the diff is returned but the file is not written.

    Returns
    -------
    dict
        ``{"ok": True, "diff": …, "dry_run": …, "applied": …}`` on success,
        or ``{"ok": False, "error": "…"}`` on failure.
    """
    if not os.path.isfile(path):
        return {"ok": False, "error": f"Not a file: {path}"}

    try:
        with open(path, "r", encoding=encoding) as f:
            original_content = f.read()
    except (UnicodeDecodeError, LookupError) as e:
        return {
            "ok": False,
            "error": f"Cannot read {path} as {encoding} text — {e}",
        }
    except OSError as e:
        return {"ok": False, "error": str(e)}

    # Reject files that contain null bytes (strong indicator of binary content)
    if "\x00" in original_content:
        return {
            "ok": False,
            "error": f"Cannot edit {path} — file appears to be binary",
        }

    # Normalise line endings (CRLF -> LF) for consistent matching
    original_content = _normalize_line_endings(original_content)
    modified_content = original_content

    for edit in edits:
        old_text = _normalize_line_endings(edit["oldText"])
        new_text = _normalize_line_endings(edit["newText"])

        if not old_text:
            continue

        # 1) Exact substring match
        if old_text in modified_content:
            modified_content = modified_content.replace(old_text, new_text, 1)
            continue

        # 2) Whitespace-flexible line-level match
        result = _try_whitespace_flexible_match(modified_content, old_text, new_text)
        if result is not None:
            modified_content = result
        else:
            return {"ok": False, "error": f"No match found for text: {old_text!r}"}

    # Build the unified diff
    diff_text = _create_unified_diff(original_content, modified_content, path)
    diff_text = _wrap_in_fence(diff_text)

    # Persist (unless dry-run)
    if not dryRun:
        try:
            tmpdir = os.path.dirname(path) or "."
            fd, tmpname = tempfile.mkstemp(dir=tmpdir, prefix=".edit_", suffix=".tmp")
            try:
                with os.fdopen(fd, "w", encoding=encoding) as f:
                    f.write(modified_content)
                os.replace(tmpname, path)
            except Exception:
                try:
                    os.unlink(tmpname)
                except OSError:
                    pass
                raise
        except OSError as e:
            return {"ok": False, "error": str(e)}

    return {
        "ok": True,
        "diff": diff_text,
        "dry_run": dryRun,
        "applied": not dryRun,
    }

"""get_file_info tool — file/directory metadata."""
import os import time
async def execute(path: str, **kwargs) -> dict: try: st = os.stat(path) except OSError as e: return {"ok": False, "error": str(e)}
return { "ok": True, "size": st.st_size, "created": time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime(st.st_ctime)), "modified": time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime(st.st_mtime)), "accessed": time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime(st.st_atime)), "isDirectory": os.path.isdir(path), "isFile": os.path.isfile(path), "permissions": oct(st.st_mode)[-3:], }

"""list_directory tool — list directory contents."""

import os


async def execute(path: str, **kwargs) -> dict:
    if not os.path.isdir(path):
        return {"ok": False, "error": f"Not a directory: {path}"}

    try:
        entries = []
        with os.scandir(path) as it:
            for entry in it:
                prefix = "[DIR]" if entry.is_dir() else "[FILE]"
                entries.append(f"{prefix} {entry.name}")
        entries.sort()
    except OSError as e:
        return {"ok": False, "error": str(e)}

    return {"ok": True, "entries": entries, "count": len(entries)}

"""list_directory_with_sizes tool — directory listing with file sizes."""

import os


def _format_size(size: int) -> str:
    units = ["B", "KB", "MB", "GB", "TB"]
    if size == 0:
        return "0 B"
    i = 0
    fsize = float(size)
    while fsize >= 1024 and i < len(units) - 1:
        fsize /= 1024
        i += 1
    return f"{fsize:.2f} {units[i]}"


async def execute(path: str, sortBy: str = "name", **kwargs) -> dict:
    if not os.path.isdir(path):
        return {"ok": False, "error": f"Not a directory: {path}"}

    try:
        detailed = []
        with os.scandir(path) as it:
            for entry in it:
                try:
                    st = entry.stat()
                    detailed.append({
                        "name": entry.name,
                        "is_dir": entry.is_dir(),
                        "size": st.st_size if not entry.is_dir() else 0,
                    })
                except OSError:
                    detailed.append({
                        "name": entry.name,
                        "is_dir": entry.is_dir(),
                        "size": 0,
                    })
    except OSError as e:
        return {"ok": False, "error": str(e)}

    if sortBy == "size":
        detailed.sort(key=lambda x: x["size"], reverse=True)
    else:
        detailed.sort(key=lambda x: x["name"])

    entries = []
    for d in detailed:
        prefix = "[DIR]" if d["is_dir"] else "[FILE]"
        size_str = "" if d["is_dir"] else _format_size(d["size"]).rjust(10)
        entries.append(f"{prefix} {d['name']:<30} {size_str}")

    total_files = sum(1 for d in detailed if not d["is_dir"])
    total_dirs = sum(1 for d in detailed if d["is_dir"])
    total_size = sum(d["size"] for d in detailed)

    entries.append("")
    entries.append(f"Total: {total_files} files, {total_dirs} directories")
    entries.append(f"Combined size: {_format_size(total_size)}")

    return {
        "ok": True,
        "entries": entries,
        "total_files": total_files,
        "total_dirs": total_dirs,
        "combined_size": total_size,
        "combined_size_human": _format_size(total_size),
    }

"""move_file tool — move/rename files and directories."""
import os
import shutil


async def execute(source: str, destination: str, **kwargs) -> dict:
    if not os.path.exists(source):
        return {"ok": False, "error": f"Source does not exist: {source}"}

    if os.path.exists(destination):
        return {"ok": False, "error": f"Destination already exists: {destination}"}

    dest_parent = os.path.dirname(destination)
    if dest_parent and not os.path.isdir(dest_parent):
        os.makedirs(dest_parent, exist_ok=True)

    try:
        shutil.move(source, destination)
    except OSError as e:
        return {"ok": False, "error": str(e)}

    return {"ok": True, "source": source, "destination": destination}

"""read_media_file tool — read image/audio as base64."""

import base64
import os

MIME_TYPES: dict[str, str] = {
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
    ".webp": "image/webp",
    ".bmp": "image/bmp",
    ".svg": "image/svg+xml",
    ".mp3": "audio/mpeg",
    ".wav": "audio/wav",
    ".ogg": "audio/ogg",
    ".flac": "audio/flac",
}

MAX_SIZE_BYTES = 10 * 1024 * 1024  # 10 MB


async def execute(path: str, **kwargs) -> dict:
    if not os.path.isfile(path):
        return {"ok": False, "error": f"Not a file: {path}"}

    ext = os.path.splitext(path)[1].lower()
    mime_type = MIME_TYPES.get(ext, "application/octet-stream")

    try:
        size = os.path.getsize(path)
        if size > MAX_SIZE_BYTES:
            return {"ok": False, "error": f"File too large: {size} bytes (max {MAX_SIZE_BYTES})"}

        with open(path, "rb") as f:
            data = f.read()
    except OSError as e:
        return {"ok": False, "error": str(e)}

    encoded = base64.b64encode(data).decode("ascii")

    if mime_type.startswith("image/"):
        media_type = "image"
    elif mime_type.startswith("audio/"):
        media_type = "audio"
    else:
        media_type = "blob"

    return {
        "ok": True,
        "type": media_type,
        "data": encoded,
        "mimeType": mime_type,
        "size_bytes": size,
    }

"""read_multiple_files tool — batch read files with per-file error tolerance."""
import asyncio
import os


async def _read_one(path: str, encoding: str = "utf-8") -> dict:
    try:
        if not os.path.isfile(path):
            return {"path": path, "ok": False, "error": f"Not a file: {path}"}
        with open(path, "r", encoding=encoding) as f:
            content = f.read()
        return {"path": path, "ok": True, "content": content}
    except (UnicodeDecodeError, LookupError) as e:
        return {"path": path, "ok": False, "error": f"Cannot read as {encoding} text — {e}"}
    except OSError as e:
        return {"path": path, "ok": False, "error": str(e)}


async def execute(paths: list[str], encoding: str = "utf-8", **kwargs) -> dict:
    if not paths:
        return {"ok": False, "error": "At least one path is required"}

    results = await asyncio.gather(*(_read_one(p, encoding) for p in paths))

    return {
        "ok": True,
        "results": results,
        "total": len(results),
        "succeeded": sum(1 for r in results if r["ok"]),
        "failed": sum(1 for r in results if not r["ok"]),
    }

"""read_text_file tool — read file content as text."""
import os


async def execute(path: str, head: int | None = None, tail: int | None = None,
                  encoding: str = "utf-8", **kwargs) -> dict:
    if head is not None and tail is not None:
        return {"ok": False, "error": "Cannot specify both head and tail parameters simultaneously"}

    if not os.path.isfile(path):
        return {"ok": False, "error": f"Not a file: {path}"}

    try:
        with open(path, "r", encoding=encoding) as f:
            lines = f.readlines()
    except (UnicodeDecodeError, LookupError) as e:
        return {"ok": False, "error": f"Cannot read {path} as {encoding} text — {e}"}
    except OSError as e:
        return {"ok": False, "error": str(e)}

    total_lines = len(lines)

    if tail is not None:
        lines = lines[-tail:]
    elif head is not None:
        lines = lines[:head]

    numbered = []
    for i, line in enumerate(lines):
        line_num = 1 + i
        if tail is not None:
            line_num = total_lines - len(lines) + 1 + i
        elif head is not None:
            line_num = 1 + i
        else:
            line_num = 1 + i
        numbered.append(f"{line_num}\t{line.rstrip()}")

    return {
        "ok": True,
        "content": "\n".join(numbered),
        "lines_read": len(lines),
        "total_lines": total_lines,
    }

"""search_content tool — recursive file content search (grep)."""

import fnmatch
import os
import re

DEFAULT_EXCLUDES = [".git", "__pycache__", "node_modules", ".venv", ".mypy_cache", ".pytest_cache", "*.pyc", "*.pyo"]

# File extensions likely to be text — everything else skipped
TEXT_EXTENSIONS: set[str] | None = None  # None = search all files


def _is_text_file(filepath: str) -> bool:
    """Heuristic: skip known binary extensions."""
    ext = os.path.splitext(filepath)[1].lower()
    if ext in {".png", ".jpg", ".jpeg", ".gif", ".webp", ".bmp",
               ".ico", ".svg", ".mp3", ".wav", ".ogg", ".flac",
               ".mp4", ".mov", ".avi", ".mkv", ".webm",
               ".zip", ".tar", ".gz", ".bz2", ".xz", ".7z",
               ".pdf", ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx",
               ".ttf", ".otf", ".woff", ".woff2", ".eot",
               ".pyc", ".pyo", ".so", ".dll", ".dylib", ".exe",
               ".db", ".sqlite", ".sqlite3", ".class", ".jar"}:
        return False
    return True


def _matches_any(name: str, patterns: list[str]) -> bool:
    for pat in patterns:
        if fnmatch.fnmatch(name, pat):
            return True
    return False


async def execute(
    pattern: str,
    path: str,
    regex: bool = False,
    include: str | None = None,
    excludePatterns: list[str] | None = None,
    maxResults: int = 100,
    **kwargs,
) -> dict:
    if not os.path.isdir(path):
        return {"ok": False, "error": f"Not a directory: {path}"}

    # Compile search pattern
    if regex:
        try:
            compiled = re.compile(pattern)
        except re.error as e:
            return {"ok": False, "error": f"Invalid regex: {e}"}
    else:
        compiled = re.compile(re.escape(pattern))

    # Build include/exclude filter lists
    include_globs: list[str] = []
    if include:
        include_globs = [g.strip() for g in include.split(",") if g.strip()]

    excludes = (excludePatterns or []) + DEFAULT_EXCLUDES

    matches: list[dict] = []
    truncated = False

    try:
        for dirpath, dirnames, filenames in os.walk(path):
            # Filter directories in-place
            dirnames[:] = [d for d in dirnames if not _matches_any(d, excludes)]

            for filename in filenames:
                filepath = os.path.join(dirpath, filename)
                relpath = os.path.relpath(filepath, path)

                # Exclude check
                if _matches_any(relpath, excludes):
                    continue

                # Include filter
                if include_globs and not any(
                    fnmatch.fnmatch(relpath, g) for g in include_globs
                ):
                    continue

                # Binary skip
                if not _is_text_file(filepath):
                    continue

                # Search file content
                try:
                    with open(filepath, "r", encoding="utf-8", errors="surrogateescape") as f:
                        for line_num, line in enumerate(f, 1):
                            if compiled.search(line):
                                matches.append({
                                    "file": relpath,
                                    "line": line.rstrip("\n\r"),
                                    "line_number": line_num,
                                })
                                if len(matches) >= maxResults:
                                    truncated = True
                                    break
                except (UnicodeDecodeError, PermissionError, OSError):
                    continue

                if truncated:
                    break

            if truncated:
                break
    except PermissionError:
        pass

    return {
        "ok": True,
        "pattern": pattern,
        "regex": regex,
        "matches": matches,
        "count": len(matches),
        "truncated": truncated,
    }

"""search_files tool — recursive glob search."""

import fnmatch
import glob
import os

DEFAULT_EXCLUDES = [".git", "__pycache__", "node_modules", ".venv", ".mypy_cache", ".pytest_cache", "*.pyc"]
MAX_RESULTS = 500


async def execute(
    path: str, pattern: str, excludePatterns: list[str] | None = None, **kwargs
) -> dict:
    if not os.path.isdir(path):
        return {"ok": False, "error": f"Not a directory: {path}"}

    excludes = (excludePatterns or []) + DEFAULT_EXCLUDES
    matches = []
    truncated = False

    try:
        if not pattern.startswith("**"):
            pattern = f"**/{pattern}"
        for rel in glob.glob(pattern, root_dir=path, recursive=True):
            if _matches_any(rel, excludes):
                continue
            matches.append(rel)
            if len(matches) >= MAX_RESULTS:
                truncated = True
                break
    except PermissionError:
        pass

    return {
        "ok": True,
        "matches": matches,
        "count": len(matches),
        "truncated": truncated,
    }


def _matches_any(name: str, patterns: list[str]) -> bool:
    for pat in patterns:
        if fnmatch.fnmatch(name, pat):
            return True
    return False

"""write_file tool — atomic file write."""

import os
import tempfile


async def execute(path: str, content: str, **kwargs) -> dict:
    parent = os.path.dirname(path)
    if parent and not os.path.isdir(parent):
        os.makedirs(parent, exist_ok=True)

    try:
        # Try exclusive creation first
        with open(path, "x", encoding="utf-8") as f:
            f.write(content)
    except FileExistsError:
        # Atomic overwrite: write to temp then rename
        tmpdir = os.path.dirname(path) or "."
        try:
            fd, tmpname = tempfile.mkstemp(dir=tmpdir, prefix=".write_", suffix=".tmp")
            try:
                with os.fdopen(fd, "w", encoding="utf-8") as f:
                    f.write(content)
                os.replace(tmpname, path)
            except Exception:
                try:
                    os.unlink(tmpname)
                except OSError:
                    pass
                raise
        except OSError as e:
            return {"ok": False, "error": str(e)}
    except OSError as e:
        return {"ok": False, "error": str(e)}

    return {"ok": True, "path": path, "bytes_written": len(content.encode("utf-8"))}

"""User-triggered memory extraction via tool call.""" import json import subprocess from pathlib import Path
async def execute(session_id: str = "", memory_dir: str = "", data_dir: str = "", force: bool = False) -> dict: """Read session state from FileStateStore, spawn extractor subprocess.
*session_id* is injected by the engine — not declared as a tool param. """ data_path = Path(data_dir or "./data") state_file = data_path / session_id / "state" / f"{session_id}.json" if not state_file.exists(): return {"ok": False, "error": f"No session state found: {state_file}"}
state = json.loads(state_file.read_text(encoding="utf-8")) messages = state.get("messages", []) if not messages: return {"ok": False, "error": "No messages to extract from"}
memory_path = Path(memory_dir or "./data/memory") memory_path.mkdir(parents=True, exist_ok=True) tmp_dir = memory_path / "state" tmp_dir.mkdir(parents=True, exist_ok=True) tmp_file = tmp_dir / f"extract_{session_id}.json" tmp_file.write_text(json.dumps(messages, ensure_ascii=False), encoding="utf-8")
extractor = Path(__file__).parent / "extractor.py" subprocess.Popen( ["python", str(extractor), "--session-file", str(tmp_file), "--memory-dir", str(memory_path), "--session-id", session_id], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, ) return {"ok": True, "message": "Memory extraction started in background"}

"""Load resident memory from memory.md for agent context recall."""
from pathlib import Path


async def execute(memory_dir: str = "") -> dict:
    memory_path = Path(memory_dir or "./data/memory") / "memory.md"
    if not memory_path.exists():
        return {"ok": True, "content": "", "message": "No resident memory yet"}

    content = memory_path.read_text(encoding="utf-8")
    return {"ok": True, "content": content, "size": len(content)}

"""plan_create — validate dependency graph and persist plan.json.""" import json import time from pathlib import Path
from arf.plugins.plan_solve.validation import validate_steps
async def execute( task: str, steps: list[dict], _engine=None, _workspace: str = "", ) -> dict: """Validate steps DAG and write plan.json to workspace.""" if not task or not task.strip(): return {"ok": False, "error": "task must be a non-empty string"}
if not steps: return {"ok": False, "error": "steps list is empty", "suggestion": "Provide at least one step"}
# Validate the dependency graph validation = validate_steps(steps) if not validation["ok"]: return validation
# Initialize step metadata plan_id = f"plan-{int(time.time())}" now = time.time() initialized_steps = [] for s in steps: initialized_steps.append({ "index": s["index"], "description": s.get("description", ""), "tool_hint": s.get("tool_hint", ""), "status": "pending", "depends_on": s.get("depends_on", []), "blocks": s.get("blocks", []), "sub_session_id": None, "result": None, "error": None, "started_at": None, "finished_at": None, })
plan = { "plan_id": plan_id, "task": task.strip(), "status": "executing", "created_at": now, "updated_at": now, "steps": initialized_steps, }
# Persist to workspace workspace = Path(_workspace) if _workspace else Path("workspace/default") workspace.mkdir(parents=True, exist_ok=True) plan_file = workspace / "plan.json" plan_file.write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8")
return { "ok": True, "plan_id": plan_id, "task": task.strip(), "steps": initialized_steps, "count": len(initialized_steps), }

"""plan_dispatch — execute a single plan step in an isolated sub-agent.""" import json import time from pathlib import Path
from arf.engine.control_plane import ControlPlane from arf.engine.checkpoint import InMemoryStateStore from arf.event_bus import InMemoryEventBus
async def execute( step_index: int, prompt_override: str = "", _engine=None, _workspace: str = "", ) -> dict: """Execute a plan step after validating its dependencies are met.""" workspace = Path(_workspace) if _workspace else Path("workspace/default") plan_file = workspace / "plan.json"
if not plan_file.exists(): return {"ok": False, "error": f"no plan found at {workspace}"}
plan = json.loads(plan_file.read_text(encoding="utf-8")) step = _find_step(plan, step_index) if step is None: return {"ok": False, "error": f"step {step_index} not found in plan"}
# Precondition: dependencies must be done blocked = [d for d in step.get("depends_on", []) if _step_status(plan, d) != "done"] if blocked: return { "ok": False, "error": f"step {step_index} is blocked: depends on steps {blocked} which are not done", "blocked_by": blocked, }
if step["status"] != "pending": return {"ok": False, "error": f"step {step_index} is already {step['status']}"}
# Mark running step["status"] = "running" step["started_at"] = time.time() plan["updated_at"] = time.time() plan_file.write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8")
# Emit started event (if engine has event_bus) if _engine and hasattr(_engine, "event_bus") and _engine.event_bus: from arf.core.events import AgentEvent _engine.event_bus.emit(AgentEvent( type="plan_step_started", data={"plan_id": plan["plan_id"], "step_index": step_index, "description": step["description"]}, ))
# Build and run sub-engine prompt = prompt_override.strip() or step["description"] session_id = f"plan_step_{plan['plan_id']}_{step_index}_{int(time.time() * 1000)}" sub_state_store = InMemoryStateStore() sub_event_bus = InMemoryEventBus() sub_engine = ControlPlane( max_turns=10, state_store=sub_state_store, tool_executor=_engine.tool_executor if _engine else None, event_bus=sub_event_bus, call_model=_engine._call_model if _engine else None, workspace_dir=str(workspace), )
state = { "session_id": session_id, "agent_name": "plan_step", "messages": [{"role": "user", "content": prompt}], "current_model": "", "current_turn": 0, "interaction_round": 0, "context_summary": "", "tool_results": {}, "plan": None, "metadata": {}, "session_active": True, }
try: result_state = await sub_engine.invoke(state) except Exception as exc: step["status"] = "failed" step["error"] = str(exc) step["finished_at"] = time.time() plan["updated_at"] = time.time() plan_file.write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8") return {"ok": False, "error": f"sub-agent crashed: {exc}", "step_index": step_index}
# Extract result from last assistant message content = "" for m in reversed(result_state.get("messages", [])): if m.get("role") == "assistant" and m.get("content", "").strip(): content = m["content"].strip() break
step["status"] = "done" step["result"] = {"content": content} step["sub_session_id"] = session_id step["finished_at"] = time.time() plan["updated_at"] = time.time() plan_file.write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8")
# Emit finished event if _engine and hasattr(_engine, "event_bus") and _engine.event_bus: from arf.core.events import AgentEvent _engine.event_bus.emit(AgentEvent( type="plan_step_finished", data={"plan_id": plan["plan_id"], "step_index": step_index, "status": "done", "content": content}, ))
return {"ok": True, "content": content, "step_index": step_index, "session_id": session_id}
def _find_step(plan: dict, step_index: int) -> dict | None: for s in plan.get("steps", []): if s["index"] == step_index: return s return None
def _step_status(plan: dict, step_index: int) -> str: s = _find_step(plan, step_index) return s["status"] if s else "unknown"

"""plan_status — read-only plan progress snapshot.""" import json from pathlib import Path
async def execute( _engine=None, _workspace: str = "", ) -> dict: """Return current plan progress.""" workspace = Path(_workspace) if _workspace else Path("workspace/default") plan_file = workspace / "plan.json"
if not plan_file.exists(): return {"ok": False, "error": f"no plan found at {workspace}"}
plan = json.loads(plan_file.read_text(encoding="utf-8")) return { "ok": True, "plan_id": plan["plan_id"], "task": plan["task"], "status": plan["status"], "created_at": plan.get("created_at"), "updated_at": plan.get("updated_at"), "steps": plan.get("steps", []), "count": len(plan.get("steps", [])), }

"""plan_summarize — validate all steps done/failed, then call model to summarize.""" import json import time from pathlib import Path
async def execute( _engine=None, _workspace: str = "", ) -> dict: """Summarize plan results after all steps complete.""" workspace = Path(_workspace) if _workspace else Path("workspace/default") plan_file = workspace / "plan.json"
if not plan_file.exists(): return {"ok": False, "error": f"no plan found at {workspace}"}
plan = json.loads(plan_file.read_text(encoding="utf-8")) steps = plan.get("steps", [])
pending_steps = [s["index"] for s in steps if s["status"] in ("pending", "running")] if pending_steps: return { "ok": False, "error": f"cannot summarize: steps {pending_steps} are still pending or running", "pending_steps": pending_steps, }
# Build context from step results results_text = "" for s in steps: content = "" if s.get("result") and isinstance(s["result"], dict): content = s["result"].get("content", "") results_text += f"\n## Step {s['index']}: {s['description']} ({s['status']})\n{content}\n"
prompt = ( f"## Task: {plan['task']}\n\n" f"Below are the results of each step. Synthesize a clear, concise summary:\n" f"{results_text}\n\n" f"Provide the final result as a single coherent response." )
if _engine is not None and hasattr(_engine, '_call_model'): response = await _engine._call_model( [{"role": "user", "content": prompt}], model_name="", ) summary = response.get("content", "") if isinstance(response, dict) else str(response) else: summary = results_text
plan["status"] = "done" plan["updated_at"] = time.time() plan_file.write_text(json.dumps(plan, ensure_ascii=False, indent=2), encoding="utf-8")
return {"ok": True, "summary": summary.strip(), "plan_id": plan["plan_id"]}

"""undo -- roll back N interaction rounds (state + files)."""


async def execute(steps: int = 1, session_id: str = "default",
                  _engine=None, _state_store=None) -> dict:
    """Call the engine's undo mechanism and return status."""
    try:
        if _engine is None:
            return {"ok": False, "error": "Engine not available"}

        available = _engine.checkpoint_count()
        if available < steps:
            return {
                "ok": False,
                "error": f"Only {available} checkpoints available, requested {steps}",
                "available": available,
            }

        restored = _engine.undo(steps, session_id=session_id)
        if restored is None:
            return {"ok": False, "error": "No checkpoints available"}

        if _state_store:
            await _state_store.put(session_id, restored)
        msg_count = len(restored.get("messages", []))
        remaining = _engine.checkpoint_count()

        return {
            "ok": True,
            "steps": steps,
            "session_id": session_id,
            "messages_restored": msg_count,
            "remaining_checkpoints": remaining,
            "note": "Conversation and files have been rolled back. Continue from here."
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}
